        dist[0][0] = grid[0][0]
        q = deque([(0, 0)])

        while q:
            r, c = q.popleft()
            if r == m - 1 and c == n - 1:
                break
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n:
                    cost = grid[nr][nc]
                    if dist[r][c] + cost < dist[nr][nc]:
                        dist[nr][nc] = dist[r][c] + cost
                        if cost == 0:
                            q.appendleft((nr, nc))
                        else:
