#include <vector>
#include <deque>

class Solution {
public:
    bool findSafeWalk(std::vector<std::vector<int>>& grid, int health) {
        int m = grid.size(), n = grid[0].size();
        std::vector<std::vector<int>> dist(m, std::vector<int>(n, 1e9));
        dist[0][0] = grid[0][0];

        std::deque<std::pair<int, int>> q;
        q.push_back({0, 0});
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        while (!q.empty()) {
            auto [r, c] = q.front();
            q.pop_front();

            for (int d = 0; d < 4; ++d) {
                int nr = r + dirs[d][0], nc = c + dirs[d][1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                    int cost = grid[nr][nc];
                    if (dist[r][c] + cost < dist[nr][nc]) {
                        dist[nr][nc] = dist[r][c] + cost;
                        if (cost == 0) q.push_front({nr, nc});
                        else q.push_back({nr, nc});
                    }
                }
            }
        }

        return dist[m - 1][n - 1] < health;
    }
};

import java.util.*;

class Solution {
    public boolean findSafeWalk(List<List<Integer>> grid, int health) {
        int m = grid.size(), n = grid.get(0).size();
        int[][] dist = new int[m][n];
        for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);
        dist[0][0] = grid.get(0).get(0);

        Deque<int[]> q = new ArrayDeque<>();
        q.offer(new int[]{0, 0});
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        while (!q.isEmpty()) {
            int[] curr = q.pollFirst();
            int r = curr[0], c = curr[1];

            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                    int cost = grid.get(nr).get(nc);
                    if (dist[r][c] + cost < dist[nr][nc]) {
                        dist[nr][nc] = dist[r][c] + cost;
                        if (cost == 0) q.offerFirst(new int[]{nr, nc});
                        else q.offerLast(new int[]{nr, nc});
                    }
                }
            }
        }

        return dist[m - 1][n - 1] < health;
    }
}

var findSafeWalk = function(grid, health) {
    const m = grid.length, n = grid[0].length;
    const dist = Array.from({ length: m }, () => new Int32Array(n).fill(1e9));
    dist[0][0] = grid[0][0];

    const q = [[0, 0]];
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];

    while (q.length > 0) {
        const [r, c] = q.shift();
        const curDist = dist[r][c];

        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                const cost = grid[nr][nc];
                if (curDist + cost < dist[nr][nc]) {
                    dist[nr][nc] = curDist + cost;
                    if (cost === 0) {
                        q.unshift([nr, nc]);
                    } else {
                        q.push([nr, nc]);
                    }
                }
            }
        }
    }

    return dist[m - 1][n - 1] < health;
};
